  await fs.writeFile(path.join(dFolder, 'evidence.json'), JSON.stringify({ ...fixture.input, clip_id: 'c'.repeat(64) }));
  await fs.writeFile(path.join(dFolder, 'first-pass-target.json'), JSON.stringify({ ...fixture.target, title: dTitle }));
  const dNotes = (await fs.readFile(path.join(__dirname, 'fixtures/reel-draft/notes.md'), 'utf8')).replace(fixture.target.title, dTitle);
