  const base = path.join(root, 'vault', 'Companion'), intake = path.join(base, '.intake'), ledgerFile = path.join(intake, 'ledger.json');
  const ledgerBytes = await fs.readFile(ledgerFile), original = JSON.parse(ledgerBytes), sourceHash = 'a'.repeat(64), capture = original.captures[sourceHash];
  expect(Object.keys(original.attempts)).toHaveLength(2); expect(capture.revisions).toHaveLength(1);
  const dCapture = original.captures['d'.repeat(64)];
  expect(Object.keys(original.captures)).toHaveLength(2); expect(dCapture.id).not.toBe(capture.id);
  expect(dCapture.title).toBe(dTitle); expect(dCapture.revisions).toHaveLength(1);
